#include <stdio.h>
#include <stdlib.h>

static int cmp_ll(const void *a, const void *b) {
    long long x = *(const long long *)a;
    long long y = *(const long long *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

int main(void) {
    long long T, N;

    if (scanf("%lld", &T) != 1) return 0;
    if (scanf("%lld", &N) != 1) return 0;

    long long *x = (long long *)malloc((size_t)N * sizeof(long long));
    if (!x) return 0;

    for (long long i = 0; i < N; i++) {
        if (scanf("%lld", &x[i]) != 1) { free(x); return 0; }
    }

    qsort(x, (size_t)N, sizeof(long long), cmp_ll);

    /* Vizinhanca da cidade mais a oeste: de 0 ate o punto medio com a segunda cidade */
    double best = (x[0] + x[1]) / 2.0;

    /* Vizinhanca da cidade mais a leste: do ponto medio com a penultima cidade ate T */
    double lastLen = (double)T - (x[N - 2] + x[N - 1]) / 2.0;
    if (lastLen < best) best = lastLen;

    /* Cidades internas: metade da soma dos intervalos aos vizinhos */
    for (long long i = 1; i < N - 1; i++) {
        double len = (x[i + 1] - x[i - 1]) / 2.0;
        if (len < best) best = len;
    }

    printf("%.2f\n", best);

    free(x);
    return 0;
}
